-- preflight for 27 (SELECT only): per published set - items out of official order, existing drafts
-- generated by scripts/prod-open/sat-order-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched; items unchanged, only positions rearranged inside each module.

select s.name, s.version_no,
  (select count(*) from (
  with k as (select i.id, i.section, i.module_key, coalesce(i.route::text, '') as rt, i.position, coalesce(ord.ka, 99) as ka, coalesce(ord.kb, 0) as kb, case i.difficulty when 'easy' then 0 when 'medium' then 1 else 2 end as d
             from mock_exam_set_items i left join (values ('rw','words_in_context',0,0), ('rw','text_structure_purpose',0,1), ('rw','cross_text_connections',0,2), ('rw','central_ideas_details',1,0), ('rw','command_of_evidence_quant',1,1), ('rw','command_of_evidence_text',1,2), ('rw','inferences',1,3), ('rw','form_structure_sense',2,0), ('rw','boundaries',2,0), ('rw','transitions',3,0), ('rw','rhetorical_synthesis',3,1), ('math','probability',3.5,0), ('math','inference_margin_error',8.3,0), ('math','evaluating_statistical_claims',8.3,0), ('math','two_variable_data',9.4,0), ('math','linear_equations_one_var',9.7,0), ('math','linear_functions',11.3,0), ('math','linear_inequalities',12.3,0), ('math','equivalent_expressions',13.2,0), ('math','ratios_rates_units',14.8,0), ('math','percentages',14.8,0), ('math','lines_angles_triangles',14.8,0), ('math','linear_equations_two_var',15.1,0), ('math','systems_linear',15.1,0), ('math','nonlinear_functions',15.6,0), ('math','one_variable_data',16.8,0), ('math','nonlinear_equations_systems',17.1,0), ('math','area_volume',17.1,0), ('math','right_triangles_trigonometry',19.1,0), ('math','circles',19.5,0)) as ord(section, skill, ka, kb) on ord.section = i.section and ord.skill = i.skill_code where i.exam_set_id = s.id),
  a as (select k.*, row_number() over (partition by module_key, rt order by ka, kb, d, position) as orn, row_number() over (partition by module_key, rt order by position) as prn from k)
  select a.id, p.position as new_position, a.position as old_position, a.module_key, a.rt from a join a p on p.module_key = a.module_key and p.rt = a.rt and p.prn = a.orn) np where np.new_position <> np.old_position) as items_to_move,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft') as existing_drafts,
  (select count(*) from mock_exam_attempts a where a.exam_set_id = s.id) as attempts_on_published
from mock_exam_sets s where s.status = 'published' and s.archived_at is null and s.name ~ '^SAT Practice Test [0-9]+$' order by length(s.name), s.name;
